int IsPalindrome(char *word)
{
    int left = 0;
    int right = strlen(word) - 1;

    while (left < right) {
        if (word[left] != word[right]) {
            return 0; 
        }
        left++;
        right--;
    }

    return 1; 

},"If the input word is 'radar', what are the values of 'left' and 'right' immediately before the while loop terminates?","If the input word is 'apple', at which index does the first mismatch occur, and what is the return value of the function?","left = 2, right = 2",Index 0 ('a') and index 4 ('e') mismatch

int IsPalindrome(char *word)
{
    int n = strlen(word);
    for (int i = 0; i < (n / 2); i++) {
        if (word[i]!=word[n-i-1]) {
            return 0;
            break;
        }
    }
    return 1;
},"If the input word is 'radar', what is the value of the variable 'i' when the loop terminates?","If the input word is 'apple', at which index 'i' does the function first encounter a mismatch and return 0?",2,0,"#include <stdio.h>

int IsPalindrome(char *word)
{
    int length = strlen(word);

    for (int i = 0; i < length / 2; i++) {
        if (word[i] != word[length - 1 - i]) {
            return 0;
        }
    }
    return 1;
},"If the input word is 'radar', what is the value of the expression (length - 1 - i) during the first iteration of the loop (when i = 0)?","If the input word is 'apple', at which index 'i' does the function first encounter a mismatch and return 0?",4,0,"#include <stdio.h>

